function output=run_adaptive_survivor_boundary(outputDir)
% Adaptive fixed-anchor bracketing of clinically repairable support deletion.
narginchk(1,1);here=fileparts(mfilename('fullpath'));root=fileparts(fileparts(here));add_paths(root,here);create_empty(outputDir);
artifactFile=fullfile(root,'results','task25_27_pipeline_20deg.mat');stage1File=fullfile(root,'results','full_integrated_layer_20deg_job22180','alpha_0p3','alpha_0p3_final.mat');baseFile=fullfile(root,'results','survivor_compression_boundary_job22813','survivor_compression_boundary_complete.mat');
source=load(artifactFile,'cfg','machine','dij','stf','pln','map');stage1=load(stage1File,'final','finalDose','supportMask');base=load(baseFile,'output');base=base.output;
patient=load(source.cfg.patientFile,'ct','cst');cfg=merge_structs(default_config(),source.cfg);allowedFull=reshape(logical(stage1.supportMask),[],1);assert(nnz(allowedFull)==136409);
[dij,toFull,~,map]=reduce_dij_to_support(source.dij,allowedFull,source.map);for i=1:numel(map),map(i).originalGlobalIx=map(i).globalIx;map(i).globalIx=i;end
[groups,~]=build_group_index(map);[groupsFull,~]=build_group_index(source.map);D=nominal(dij);model=build_matrad_dose_model(dij,patient.cst,source.pln,0);A=state_matrix(model);zeroTol=1e-10;
wRef=reshape(double(stage1.final.w(toFull)),[],1);reference=evaluate_plan(wRef,model,D,patient,cfg,source,groupsFull,toFull,stage1.final.w);anchorW=reshape(double(base.w),[],1);anchor=evaluate_plan(anchorW,model,D,patient,cfg,source,groupsFull,toFull,stage1.final.w);assert(anchor.activeSpots==133790&&anchor.activeLayers==723&&clinical_accept(anchor,reference,[],true).pass);
spec=build_clinical_gate_spec(D,patient.cst,reference.dose,2,0.2);geom=geometry_arrays(map,source.stf);settings=struct('initialStep',1354,'knownLower',677,'maxStep',8192,'minBracketWidth',256,'maxSurvivorSolves',6,'candidateBlocks',8,'maxRescue',512,'maxLocalSurvivors',1800,'zeroTolerance',zeroTol);
[g,components]=objective_information(model,A,anchorW);[anchorGateVals,anchorGateJ]=evaluate_clinical_gates(D,anchorW,spec,true);supportAnchor=anchorW>zeroTol;historicalDormant=~supportAnchor;
attempts=repmat(empty_attempt(),0,1);features=repmat(empty_feature(),0,1);layers=repmat(empty_layer(),0,1);componentRows=repmat(empty_component(),0,1);gateRows=repmat(empty_gate(),0,1);runtime=repmat(empty_runtime(),0,1);mapping=repmat(empty_mapping(),0,1);
lower=settings.knownLower;upper=NaN;step=settings.initialStep;solveCount=0;attemptId=0;best=[];failure=[];failureConfirmed=false;numericalStop=false;total=tic;
while solveCount<settings.maxSurvivorSolves
 attemptId=attemptId+1;[death,spotTable,feat,layerTable,pool]=propose(anchorW,g,components,anchorGateJ,spec,model,D,map,groups,geom,step,settings,1);
 writetable(spotTable,fullfile(outputDir,sprintf('attempt_%02d_spots.csv',attemptId)));[trial,run,raw,gate,cls]=solve_trial(death,anchorW,supportAnchor,dij,patient,cfg,source,groupsFull,toFull,stage1.final.w,reference);solveCount=solveCount+1;
 [cRows,rawComponents]=component_changes(attemptId,components,model,A,anchorW,death);componentRows=[componentRows;cRows];feat=complete_feature(feat,attemptId,1,raw,trial.plan,anchor,anchorGateVals,spec,gate,run);features(end+1)=feat;layers=[layers;stamp_layers(layerTable,attemptId,1)];gateRows=[gateRows;gate_rows(attemptId,1,'raw',raw,reference);gate_rows(attemptId,1,'survivor',trial.plan,reference)];runtime(end+1)=runtime_row(attemptId,1,run,pool.finiteCalls);attempts(end+1)=attempt_row(attemptId,1,step,'PRIMARY',cls,anchor,raw,trial.plan,death,gate,run,toc(total)); %#ok<AGROW>
 save(fullfile(outputDir,sprintf('attempt_%02d.mat',attemptId)),'death','trial','run','raw','gate','cls','feat','rawComponents','-v7.3');flush(outputDir,attempts,features,layers,componentRows,gateRows,runtime,mapping);
 fprintf('ADAPTIVE attempt=%d step=%d class=%s spots=%d layers=%d obj=%.6f bdt=%.3f primal=%.3e dual=%.3e\n',attemptId,step,cls,trial.plan.activeSpots,trial.plan.activeLayers,trial.plan.objective,trial.plan.delivery.T_total,run.primalInfeasibility,run.dualInfeasibility);
 if strcmp(cls,'SURVIVOR_REPAIR_SUCCESS')
  lower=step;if isempty(best)||step>best.step,best=struct('step',step,'death',death,'trial',trial,'gate',gate,'run',run);end
  if isnan(upper),if step>=settings.maxStep,break;end;step=min(settings.maxStep,2*step);else,if upper-lower<=settings.minBracketWidth,break;end;step=round64((lower+upper)/2);end
 elseif strcmp(cls,'SURVIVOR_REPAIR_FAILURE')
  firstFailure=isnan(upper);upper=step;failure=struct('step',step,'death',death,'trial',trial,'gate',gate,'run',run);
  % One matched independent block confirms only the first failed cardinality.
  if firstFailure
   attemptId=attemptId+1;[d2,s2,f2,l2,p2]=propose(anchorW,g,components,anchorGateJ,spec,model,D,map,groups,geom,step,settings,2);writetable(s2,fullfile(outputDir,sprintf('attempt_%02d_spots.csv',attemptId)));
   [t2,r2,raw2,ga2,cl2]=solve_trial(d2,anchorW,supportAnchor,dij,patient,cfg,source,groupsFull,toFull,stage1.final.w,reference);solveCount=solveCount+1;[cr2,rc2]=component_changes(attemptId,components,model,A,anchorW,d2);componentRows=[componentRows;cr2];f2=complete_feature(f2,attemptId,2,raw2,t2.plan,anchor,anchorGateVals,spec,ga2,r2);features(end+1)=f2;layers=[layers;stamp_layers(l2,attemptId,2)];gateRows=[gateRows;gate_rows(attemptId,2,'raw',raw2,reference);gate_rows(attemptId,2,'survivor',t2.plan,reference)];runtime(end+1)=runtime_row(attemptId,2,r2,p2.finiteCalls);attempts(end+1)=attempt_row(attemptId,2,step,'CONFIRMATION',cl2,anchor,raw2,t2.plan,d2,ga2,r2,toc(total));failureConfirmed=strcmp(cl2,'SURVIVOR_REPAIR_FAILURE');save(fullfile(outputDir,sprintf('attempt_%02d.mat',attemptId)),'d2','t2','r2','raw2','ga2','cl2','f2','rc2','-v7.3');flush(outputDir,attempts,features,layers,componentRows,gateRows,runtime,mapping);
   if ~failureConfirmed&&strcmp(cl2,'NUMERICALLY_INCONCLUSIVE'),numericalStop=true;break;end
  end
  if upper-lower<=settings.minBracketWidth||solveCount>=settings.maxSurvivorSolves,break;end;step=round64((lower+upper)/2);
 else
  numericalStop=true;break;
 end
end
boundaryFound=isfinite(upper)&&failureConfirmed;rescueTriggered=false;rescueSupported=false;stationarity=false;finalW=anchorW;
if boundaryFound&&~isempty(failure)
 rescueTriggered=true;[rescueIx,wWarm,proposal]=gate_aware_rescue(anchorW,failure.trial.w,failure.trial.support,historicalDormant,failure.death,g,spec,D,wRef,settings);save(fullfile(outputDir,'dormant_rescue_proposal.mat'),'proposal','rescueIx','-v7.3');trialSupport=failure.trial.support;trialSupport(rescueIx)=true;
 [repair,repairRun]=solve_support(dij,patient.cst,source.pln,wWarm,trialSupport,reference,patient,cfg,source,groupsFull,toFull,stage1.final.w);repairGate=clinical_accept(repair.plan,reference,repairRun,repairRun.solverUsable);birth=rescueIx(historicalDormant(rescueIx)&repair.w(rescueIx)>zeroTol);returns=failure.death(repair.w(failure.death)>zeroTol);permanent=failure.death(repair.w(failure.death)<=zeroTol);net=repair.plan.activeSpots-anchor.activeSpots;rescueSupported=repairGate.pass&&~isempty(birth)&&net<0&&numel(returns)<0.9*numel(failure.death);stationarity=repairRun.numericallyStationary;
 attempts(end+1)=rescue_row(attemptId+1,failure.step,anchor,repair.plan,failure.death,permanent,returns,birth,repairGate,repairRun,toc(total));gateRows=[gateRows;gate_rows(attemptId+1,3,'dormant_rescue',repair.plan,reference)];runtime(end+1)=runtime_row(attemptId+1,3,repairRun,0);mapping=mapping_rows(attemptId+1,failure.death,birth,map,groups,anchorW,repair.w);if rescueSupported,finalW=repair.w;elseif ~isempty(best),finalW=best.trial.w;end;save(fullfile(outputDir,'dormant_rescue_result.mat'),'repair','repairRun','repairGate','birth','returns','permanent','net','rescueSupported','-v7.3');
elseif ~isempty(best),finalW=best.trial.w;stationarity=best.run.numericallyStationary;end
final=evaluate_plan(finalW,model,D,patient,cfg,source,groupsFull,toFull,stage1.final.w);finalGate=clinical_accept(final,reference,[],true);
if boundaryFound,boundaryLabel='SURVIVOR_COMPRESSION_BOUNDARY_FOUND';else,boundaryLabel='SURVIVOR_COMPRESSION_BOUNDARY_NOT_FOUND';end
survivorLabel='REPEATED_SURVIVOR_COMPRESSION_SUPPORTED';if rescueTriggered,triggerLabel='DORMANT_REPLACEMENT_TRIGGERED';else,triggerLabel='DORMANT_REPLACEMENT_NOT_TRIGGERED';end
if stationarity,stationarityLabel='NUMERICAL_STATIONARITY_ESTABLISHED';else,stationarityLabel='NUMERICAL_STATIONARITY_NOT_ESTABLISHED';end
output=struct('boundaryLabel',boundaryLabel,'survivorLabel',survivorLabel,'dormantTriggerLabel',triggerLabel,'dormantRescueSupported',rescueSupported,'stationarityLabel',stationarityLabel,'numericalStop',numericalStop,'lowerSuccess',lower,'upperFailure',upper,'failureConfirmed',failureConfirmed,'settings',settings,'anchor',anchor,'w',finalW,'final',final,'finalGate',finalGate,'attempts',attempts,'features',features,'layers',layers,'components',componentRows,'gates',gateRows,'runtime',runtime,'mapping',mapping,'wallSeconds',toc(total));save(fullfile(outputDir,'adaptive_survivor_boundary_complete.mat'),'output','-v7.3');flush(outputDir,attempts,features,layers,componentRows,gateRows,runtime,mapping);write_report(outputDir,output);fprintf('FINAL_LABELS: %s | %s | %s | %s\n',boundaryLabel,survivorLabel,triggerLabel,stationarityLabel);
end

function [trial,run,raw,gate,cls]=solve_trial(death,w,support,dij,patient,cfg,source,groupsFull,toFull,wTemplate,reference)
s=support;s(death)=false;z=w;z(death)=0;fullModel=build_matrad_dose_model(dij,patient.cst,source.pln,0);raw=evaluate_plan(z,fullModel,nominal(dij),patient,cfg,source,groupsFull,toFull,wTemplate);[trial,run]=solve_support(dij,patient.cst,source.pln,z,s,reference,patient,cfg,source,groupsFull,toFull,wTemplate);gate=clinical_accept(trial.plan,reference,run,run.solverUsable);
if gate.pass,cls='SURVIVOR_REPAIR_SUCCESS';elseif run.status==2,cls='SURVIVOR_REPAIR_FAILURE';elseif any(run.status==[0 1])&&~gate.pass,cls='SURVIVOR_REPAIR_FAILURE';else,cls='NUMERICALLY_INCONCLUSIVE';end
end

function [sol,run]=solve_support(dij,cst,pln,wStart,support,reference,patient,cfg,source,groupsFull,toFull,wTemplate)
[dijR,r2f]=reduce_dij_to_support(dij,support);m=build_matrad_dose_model(dijR,cst,pln,0);w0=wStart(r2f);D=nominal(dijR);sp=build_clinical_gate_spec(D,cst,reference.dose,2,0.2);set=struct('ipopt',struct('max_iter',320,'max_cpu_time',160000,'print_level',3,'acceptable_iter',8,'acceptable_obj_change_tol',1e-5));run=solve_clinical_gate_ipopt(m,w0,D,sp,set);w=zeros(double(dij.totalNumOfBixels),1);w(r2f)=run.w;plan=evaluate_plan(w,build_matrad_dose_model(dij,cst,pln,0),nominal(dij),patient,cfg,source,groupsFull,toFull,wTemplate);sol=struct('w',w,'plan',plan,'support',support);
end

function [death,tbl,feat,layerTable,pool]=propose(w,g,comps,gateJ,spec,model,D,map,groups,geom,batch,s,rankChoice)
n=numel(w);active=w>s.zeroTolerance;comp=zeros(n,1);for i=1:numel(comps),comp=comp+(w.*comps(i).gradient/max(1,abs(comps(i).value))).^2;end;comp=sqrt(comp);target=zeros(n,1);oar=zeros(n,1);for i=1:numel(spec),q=abs(gateJ(i,:)'.*w);if strcmp(spec(i).sense,'lower'),target=max(target,q);else,oar=max(oar,q);end,end
score=rank01(abs(g.*w))+rank01(comp)+rank01(target)-0.2*rank01(oar);groupScore=inf(numel(groups),1);for j=1:numel(groups),ix=groups(j).ix;ix=ix(active(ix));if ~isempty(ix),groupScore(j)=median(score(ix));end,end;[~,go]=sort(groupScore,'ascend');seeds=go(1:min(s.candidateBlocks,numel(go)));cand=cell(numel(seeds),1);quality=zeros(numel(seeds),3);f0=evaluate_matrad_dose_model(model,w,false);
cpMax=max(geom.cp);for q=1:numel(seeds),seedIx=groups(seeds(q)).ix(1);dc=abs(geom.cp-geom.cp(seedIx));dc=min(dc,cpMax-dc);de=abs(geom.energyIndex-geom.energyIndex(seedIx));ds=hypot(geom.x-geom.x(seedIx),geom.y-geom.y(seedIx));geo=dc/max(1,cpMax/8)+de/max(1,max(geom.energyIndex)/4)+ds/max(10,median(ds(active)));v=geo+0.25*score;v(~active)=Inf;[~,o]=sort(v,'ascend');cand{q}=o(1:min(batch,nnz(active)));z=w;z(cand{q})=0;fq=evaluate_matrad_dose_model(model,z,false);gv=evaluate_clinical_gates(D,z,spec,false);viol=0;for h=1:numel(spec),if strcmp(spec(h).sense,'lower'),viol=max(viol,max(0,spec(h).limit-gv(h))/max(1,abs(spec(h).limit)));else,viol=max(viol,max(0,gv(h)-spec(h).limit)/max(1,abs(spec(h).limit)));end,end;quality(q,:)=[viol,max(0,fq-f0),mean(score(cand{q}))];end
[~,ord]=sortrows(quality,[1 2 3]);pick=ord(min(rankChoice,numel(ord)));death=cand{pick};layerOf=zeros(n,1);for j=1:numel(groups),layerOf(groups(j).ix)=j;end;tbl=table(death,reshape([map(death).originalGlobalIx],[],1),w(death),geom.cp(death),layerOf(death),geom.energy(death),geom.x(death),geom.y(death),abs(g(death).*w(death)),comp(death),target(death),oar(death),score(death),'VariableNames',{'allowedIx','globalIx','weight','controlPoint','layer','energy','bevX','bevY','objectiveSensitivity','componentSensitivity','targetContribution','oarContribution','combinedScore'});
affected=unique(layerOf(death));counts=zeros(numel(affected),1);weights=counts;fullRemoved=false(size(counts));for j=1:numel(affected),ix=groups(affected(j)).ix;di=intersect(ix,death);counts(j)=numel(di);weights(j)=sum(w(di));fullRemoved(j)=all(ismember(ix(active(ix)),death));end;layerTable=table(affected,counts,weights,fullRemoved,'VariableNames',{'layer','deletedSpots','deletedWeight','fullyRemoved'});
feat=empty_feature();feat.deletionSize=numel(death);feat.totalDeletedWeight=sum(w(death));feat.affectedLayers=numel(affected);feat.fullyRemovedLayers=nnz(fullRemoved);feat.affectedControlPoints=numel(unique(geom.cp(death)));feat.cpCoverageFraction=feat.affectedControlPoints/numel(unique(geom.cp(active)));feat.bevXSpan=max(geom.x(death))-min(geom.x(death));feat.bevYSpan=max(geom.y(death))-min(geom.y(death));feat.targetResponseLoss=sum(target(death));feat.oarResponseLoss=sum(oar(death));feat.meanWeight=mean(w(death));feat.maxWeight=max(w(death));pool=struct('finiteCalls',numel(cand)+1,'quality',quality,'seedLayer',seeds(pick));
end

function [rows,rawComp]=component_changes(id,comps,model,A,w,death),z=w;z(death)=0;[~,rawComp]=objective_information(model,A,z);rows=repmat(empty_component(),numel(comps),1);for i=1:numel(comps),rows(i)=struct('attempt',id,'component',i,'incumbentValue',comps(i).value,'rawDeletionValue',rawComp(i).value,'change',rawComp(i).value-comps(i).value);end,end
function f=complete_feature(f,id,rep,raw,plan,inc,anchorGate,spec,gate,run),f.attempt=id;f.replicate=rep;f.rawObjectiveChange=raw.objective-inc.objective;f.repairedObjectiveChange=plan.objective-inc.objective;f.minRawGateMargin=min_gate(raw,inc,spec);f.minRepairedGateMargin=min_gate(plan,inc,spec);f.repairClass=ternary(gate.pass,'SUCCESS','NONPASS');f.solverWallSeconds=run.wallSeconds;f.permanentDeaths=inc.activeSpots-plan.activeSpots;f.deathsPerSolve=f.permanentDeaths;f.bdtChange=plan.delivery.T_total-inc.delivery.T_total;f.bdtSecondsReducedPerWallHour=-f.bdtChange/max(run.wallSeconds/3600,eps); %#ok<INUSD>
end
function m=min_gate(p,~,spec),m=Inf;for i=1:numel(spec),q=find(strcmp({p.dose.structures.name},spec(i).structure),1);v=p.dose.structures(q).(spec(i).metric);if strcmp(spec(i).sense,'lower'),d=v-spec(i).limit;else,d=spec(i).limit-v;end;m=min(m,d);end,end

function [rescue,wWarm,p]=gate_aware_rescue(wInc,wFail,support,historical,deaths,gInc,spec,D,wRef,s)
[vals,J,rows]=evaluate_clinical_gates(D,wFail,spec,true);m=numel(vals);A=zeros(m,size(D,2));b=zeros(m,1);for i=1:m,if strcmp(spec(i).sense,'lower'),A(i,:)=-J(i,:);b(i)=vals(i)-spec(i).limit;else,A(i,:)=J(i,:);b(i)=spec(i).limit-vals(i);end,end;A=sparse(A);importance=max(abs(A),[],1)';surv=top(importance.*max(wFail,1e-8),support&(wFail>s.zeroTolerance),s.maxLocalSurvivors);eligible=unique([find(historical);deaths(:)],'stable');Jix=unique([surv;eligible],'stable');isEligible=ismember(Jix,eligible);Aj=A(:,Jix);scale=max(0.05,abs(b));lb=-wFail(Jix);lb(isEligible)=0;ub=max([abs(wFail(Jix)),abs(wRef(Jix)),ones(numel(Jix),1)],[],2);ub(isEligible)=max(2*abs(wRef(Jix(isEligible))),1);
lp=optimoptions('linprog','Algorithm','dual-simplex','Display','none');[x,~,ef]=linprog([zeros(numel(Jix),1);1],[Aj,-scale],b,[],[],[lb;0],[ub;10],lp);rho=Inf;if ef>0,rho=x(end);end;rescue=zeros(0,1);wWarm=wFail;if rho<=1e-6,H=spdiags(1./max(ub,1e-8).^2,0,numel(Jix),numel(Jix));eta=max(1e-8,1e-3*max(abs(gInc(Jix).*ub)));qp=optimoptions('quadprog','Algorithm','interior-point-convex','Display','none');[d,~,qe]=quadprog(eta*H,gInc(Jix),Aj,b,[],[],lb,ub,[],qp);if qe>0,cand=find(isEligible&d>1e-8);[~,o]=sort(d(cand),'descend');cand=cand(o(1:min(s.maxRescue,numel(o))));rescue=Jix(cand);keep=ismember(Jix,rescue);lb2=lb;ub2=ub;lb2(isEligible&~keep)=0;ub2(isEligible&~keep)=0;[d,~,qe]=quadprog(eta*H,gInc(Jix),Aj,b,[],[],lb2,ub2,[],qp);if qe>0,wWarm(Jix)=max(0,wFail(Jix)+d);else,rescue=zeros(0,1);end,end,end;p=struct('rho',rho,'localIx',Jix,'eligibleIx',eligible,'rescueIx',rescue,'gateRows',rows,'gateValues',vals);
end

function p=evaluate_plan(w,model,D,patient,cfg,source,groupsFull,toFull,wTemplate),[f,~,d]=evaluate_matrad_dose_model(model,w,false);z=zeros(size(wTemplate));z(toFull)=w;p=struct('objective',f,'maxConstraintViolation',d.maxConstraintViolation,'dose',compute_dvh_metrics(full(D*w),patient.ct,patient.cst,cfg),'delivery',compute_delivery_metrics(z,source.map,groupsFull,cfg,source.machine),'activeSpots',nnz(w>1e-10),'activeLayers',count_layers(w,build_groups(source.map,toFull),1e-10));end
function gate=clinical_accept(p,r,solver,usable),[pass,worst,detail]=dose_quality(p.dose,r.dose);gate=struct('pass',usable&&pass&&p.objective<=1.02*r.objective&&p.maxConstraintViolation<=1e-6,'dosePass',pass,'objectivePass',p.objective<=1.02*r.objective,'constraintPass',p.maxConstraintViolation<=1e-6,'worstAdverse',worst,'detail',{detail});if isempty(solver),gate.numericallyStationary=false;else,gate.numericallyStationary=solver.numericallyStationary;end,end
function [pass,worst,rows]=dose_quality(c,r),pass=true;worst=0;rows={};for i=1:numel(c.structures),a=r.structures(i);b=c.structures(i);if a.isTarget,keys={'D95','D98'};sense='lower';elseif strcmpi(a.type,'OAR')&&~ismember(upper(a.name),{'BODY','EXTERNAL'}),keys={'Dmean','Dmax'};sense='upper';else,continue;end;for k=1:numel(keys),m=keys{k};if strcmp(sense,'lower'),lim=.98*a.(m);ok=b.(m)>=lim;adv=max(0,100*(a.(m)-b.(m))/max(abs(a.(m)),eps));else,lim=a.(m)+max(.2,.02*max(abs(a.(m)),1));ok=b.(m)<=lim;adv=max(0,100*(b.(m)-a.(m))/max(abs(a.(m)),eps));end;rows(end+1,:)={a.name,m,b.(m),lim,ok};pass=pass&&ok;worst=max(worst,adv);end,end,end
function [g,c]=objective_information(model,A,w),[~,g]=evaluate_matrad_dose_model(model,w,true);x=A*w;c=repmat(struct('value',NaN,'gradient',zeros(numel(w),1)),0,1);for i=1:size(model.cst,1),vox=reshape(double(model.cst{i,4}{1}),[],1);for j=1:numel(model.cst{i,6}),o=model.cst{i,6}{j};if ~isa(o,'DoseObjectives.matRad_DoseObjective'),continue;end;o=model.optiProb.BP.setBiologicalDosePrescriptions(o,model.cst{i,5}.alphaX,model.cst{i,5}.betaX);dg=zeros(size(x));dg(vox)=o.penalty*o.computeDoseObjectiveGradient(x(vox));c(end+1)=struct('value',double(o.penalty*o.computeDoseObjectiveFunction(x(vox))),'gradient',A'*dg);end,end,end
function g=geometry_arrays(map,stf),n=numel(map);g=struct('cp',zeros(n,1),'energyIndex',zeros(n,1),'energy',zeros(n,1),'x',zeros(n,1),'y',zeros(n,1));for i=1:n,m=map(i);q=double(stf(m.beamNum).ray(m.rayNum).rayPos_bev);g.cp(i)=m.cpIndex;g.energyIndex(i)=m.energyIndex;g.energy(i)=m.energy;g.x(i)=q(1);g.y(i)=q(3);end,end
function r=empty_attempt(),r=struct('attempt',0,'replicate',0,'kind','','deletionSize',0,'classification','','proposedDeaths',0,'permanentDeaths',0,'sameEventReturns',0,'historicalDormantBirths',0,'netSupportChange',0,'objectiveBefore',NaN,'objectiveRaw',NaN,'objectiveAfter',NaN,'activeSpotsAfter',0,'activeLayersAfter',0,'bdtAfter',NaN,'dosePass',false,'objectivePass',false,'clinicalFeasibility',false,'solverStatus','','primalInfeasibility',NaN,'dualInfeasibility',NaN,'numericallyStationary',false,'wallSeconds',NaN);end
function r=attempt_row(id,rep,step,kind,cls,inc,raw,plan,deaths,gate,solver,wall),r=empty_attempt();r.attempt=id;r.replicate=rep;r.kind=kind;r.deletionSize=step;r.classification=cls;r.proposedDeaths=numel(deaths);r.permanentDeaths=inc.activeSpots-plan.activeSpots;r.netSupportChange=plan.activeSpots-inc.activeSpots;r.objectiveBefore=inc.objective;r.objectiveRaw=raw.objective;r.objectiveAfter=plan.objective;r.activeSpotsAfter=plan.activeSpots;r.activeLayersAfter=plan.activeLayers;r.bdtAfter=plan.delivery.T_total;r.dosePass=gate.dosePass;r.objectivePass=gate.objectivePass;r.clinicalFeasibility=gate.pass;r.solverStatus=solver.statusMessage;r.primalInfeasibility=solver.primalInfeasibility;r.dualInfeasibility=solver.dualInfeasibility;r.numericallyStationary=solver.numericallyStationary;r.wallSeconds=wall;end
function r=rescue_row(id,step,inc,plan,deaths,permanent,returns,births,gate,solver,wall),r=empty_attempt();r.attempt=id;r.replicate=3;r.kind='DORMANT_RESCUE';r.deletionSize=step;r.classification=ternary(gate.pass,'RESCUE_FEASIBLE','RESCUE_NONPASS');r.proposedDeaths=numel(deaths);r.permanentDeaths=numel(permanent);r.sameEventReturns=numel(returns);r.historicalDormantBirths=numel(births);r.netSupportChange=plan.activeSpots-inc.activeSpots;r.objectiveBefore=inc.objective;r.objectiveAfter=plan.objective;r.activeSpotsAfter=plan.activeSpots;r.activeLayersAfter=plan.activeLayers;r.bdtAfter=plan.delivery.T_total;r.dosePass=gate.dosePass;r.objectivePass=gate.objectivePass;r.clinicalFeasibility=gate.pass;r.solverStatus=solver.statusMessage;r.primalInfeasibility=solver.primalInfeasibility;r.dualInfeasibility=solver.dualInfeasibility;r.numericallyStationary=solver.numericallyStationary;r.wallSeconds=wall;end
function r=empty_feature(),r=struct('attempt',0,'replicate',0,'deletionSize',0,'totalDeletedWeight',0,'meanWeight',0,'maxWeight',0,'affectedLayers',0,'fullyRemovedLayers',0,'affectedControlPoints',0,'cpCoverageFraction',0,'bevXSpan',0,'bevYSpan',0,'targetResponseLoss',0,'oarResponseLoss',0,'rawObjectiveChange',0,'repairedObjectiveChange',0,'minRawGateMargin',0,'minRepairedGateMargin',0,'repairClass','','solverWallSeconds',0,'permanentDeaths',0,'deathsPerSolve',0,'bdtChange',0,'bdtSecondsReducedPerWallHour',0);end
function r=empty_layer(),r=struct('attempt',0,'replicate',0,'layer',0,'deletedSpots',0,'deletedWeight',0,'fullyRemoved',false);end
function t=stamp_layers(T,id,rep),t=repmat(empty_layer(),height(T),1);for i=1:height(T),t(i)=struct('attempt',id,'replicate',rep,'layer',T.layer(i),'deletedSpots',T.deletedSpots(i),'deletedWeight',T.deletedWeight(i),'fullyRemoved',T.fullyRemoved(i));end,end
function r=empty_component(),r=struct('attempt',0,'component',0,'incumbentValue',0,'rawDeletionValue',0,'change',0);end
function r=empty_gate(),r=struct('attempt',0,'replicate',0,'phase','','structure','','metric','','value',NaN,'limit',NaN,'pass',false);end
function r=gate_rows(id,rep,phase,p,ref),[~,~,d]=dose_quality(p.dose,ref.dose);r=repmat(empty_gate(),size(d,1),1);for i=1:size(d,1),r(i)=struct('attempt',id,'replicate',rep,'phase',phase,'structure',d{i,1},'metric',d{i,2},'value',d{i,3},'limit',d{i,4},'pass',d{i,5});end,end
function r=empty_runtime(),r=struct('attempt',0,'replicate',0,'solverWallSeconds',0,'iterations',0,'objectiveCalls',0,'gradientCalls',0,'constraintCalls',0,'jacobianCalls',0,'finiteRemovalObjectiveCalls',0);end
function r=runtime_row(id,rep,s,c),r=empty_runtime();r.attempt=id;r.replicate=rep;r.solverWallSeconds=s.wallSeconds;r.iterations=s.iterations;r.objectiveCalls=s.callbackCounts.objective;r.gradientCalls=s.callbackCounts.gradient;r.constraintCalls=s.callbackCounts.constraints;r.jacobianCalls=s.callbackCounts.jacobian;r.finiteRemovalObjectiveCalls=c;end
function r=empty_mapping(),r=struct('attempt',0,'deathGlobalIx','','birthGlobalIx',0,'birthLayer',0,'birthControlPoint',0,'weightBefore',0,'weightAfter',0);end
function r=mapping_rows(k,d,b,map,groups,w0,w1),r=repmat(empty_mapping(),numel(b),1);go=zeros(numel(map),1);for i=1:numel(groups),go(groups(i).ix)=i;end;ds=index_list([map(d).originalGlobalIx]);for i=1:numel(b),q=b(i);r(i)=struct('attempt',k,'deathGlobalIx',ds,'birthGlobalIx',map(q).originalGlobalIx,'birthLayer',go(q),'birthControlPoint',map(q).cpIndex,'weightBefore',w0(q),'weightAfter',w1(q));end,end
function flush(o,a,b,c,d,e,f,g),write(a,'adaptive_attempts.csv');write(b,'deletion_features.csv');write(c,'deleted_layer_composition.csv');write(d,'objective_component_changes.csv');write(e,'clinical_gate_trajectory.csv');write(f,'runtime_evaluations.csv');write(g,'death_birth_mapping.csv');function write(x,n),if ~isempty(x),writetable(struct2table(x,'AsArray',true),fullfile(o,n));end,end,end
function write_report(o,x),f=fopen(fullfile(o,'ADAPTIVE_SURVIVOR_BOUNDARY_REPORT.md'),'w');c=onCleanup(@()fclose(f));fprintf(f,'# Adaptive survivor-compression boundary\n\n- `%s`\n- `%s`\n- `%s`\n- `%s`\n- lower successful deletion: %g\n- upper failed deletion: %g\n- failure confirmed: %d\n- final spots/layers: %d/%d\n- final objective: %.9g\n- final BDT: %.3f s\n- all gates pass: %d\n',x.boundaryLabel,x.survivorLabel,x.dormantTriggerLabel,x.stationarityLabel,x.lowerSuccess,x.upperFailure,x.failureConfirmed,x.final.activeSpots,x.final.activeLayers,x.final.objective,x.final.delivery.T_total,x.finalGate.pass);end
function q=round64(x),q=max(64,64*round(x/64));end
function x=rank01(v),x=zeros(size(v));q=isfinite(v);if any(q),a=min(v(q));b=max(v(q));x(q)=(v(q)-a)/max(b-a,eps);end,end
function ix=top(score,mask,k),q=find(mask&isfinite(score));[~,o]=sort(score(q),'descend');ix=q(o(1:min(k,numel(o))));end
function D=nominal(d),D=d.physicalDose;if iscell(D),D=D{1};end,end
function A=state_matrix(m),A=nominal(m.dij);if isa(m.optiProb.BP,'matRad_ConstantRBEProjection'),A=double(m.dij.RBE)*A;end,end
function g=build_groups(map,toFull),m=map(toFull);for i=1:numel(m),m(i).globalIx=i;end;g=build_group_index(m);end
function n=count_layers(w,g,t),n=0;for i=1:numel(g),n=n+any(w(g(i).ix)>t);end,end
function s=index_list(ix),s=strjoin(arrayfun(@num2str,reshape(ix,1,[]),'UniformOutput',false),';');end
function y=ternary(c,a,b),if c,y=a;else,y=b;end,end
function add_paths(root,here),f={'config','planning','mapping','objective','delivery','reduction','evaluation','integrated','robustness'};for i=1:numel(f),addpath(fullfile(root,f{i}));end;addpath(fullfile(root,'experiments','repeated_dormant_replacement'));addpath(here);end
function create_empty(d),if exist(d,'dir')==7,e=dir(d);e=e(~ismember({e.name},{'.','..'}));assert(isempty(e));else,mkdir(d);end,end
function m=merge_structs(a,b),m=a;f=fieldnames(b);for i=1:numel(f),k=f{i};if isfield(m,k)&&isstruct(m.(k))&&isstruct(b.(k)),m.(k)=merge_structs(m.(k),b.(k));else,m.(k)=b.(k);end,end,end
